--------------------------------------------------------------------------------
--
-- Run this file once, from psql, with:   \i a2-2026-fleetdb.sql
-- It DROPS and recreates a database called  assignment2  and leaves you
-- connected to it.  Wait for the message "DONE! All data has been inserted."
--------------------------------------------------------------------------------

\c postgres
DROP DATABASE IF EXISTS assignment2 WITH (FORCE);
CREATE DATABASE assignment2;
\c assignment2

\set ECHO none
\set QUIET on
\timing off

\echo 'Creating tables and inserting data. This may take a minute...'

BEGIN TRANSACTION;

--- Tables ---------------------------------------------------------------------

CREATE TABLE STATIONS (
    station_id   VARCHAR PRIMARY KEY,
    station_name VARCHAR NOT NULL,
    suburb       VARCHAR NOT NULL,
    bays         INTEGER NOT NULL
);

CREATE TABLE MODELS (
    model_code        VARCHAR PRIMARY KEY,
    make              VARCHAR NOT NULL,
    model_name        VARCHAR NOT NULL,
    body_type         VARCHAR NOT NULL,
    seats             INTEGER NOT NULL,
    replacement_value INTEGER NOT NULL
);

CREATE TABLE VEHICLES (
    vehicle_id  VARCHAR PRIMARY KEY,
    model_code  VARCHAR NOT NULL REFERENCES MODELS,
    station_id  VARCHAR NOT NULL REFERENCES STATIONS,
    in_service  DATE NOT NULL,
    odometer    INTEGER NOT NULL
);

CREATE TABLE MEMBERS (
    member_id   SERIAL PRIMARY KEY,
    member_name VARCHAR NOT NULL,
    email       VARCHAR NOT NULL UNIQUE,
    joined      DATE NOT NULL,
    plan        VARCHAR NOT NULL,
    sponsor_id  INTEGER REFERENCES MEMBERS
);

CREATE TABLE BOOKING_EVENTS (
    event_id   SERIAL PRIMARY KEY,
    member_id  INTEGER NOT NULL REFERENCES MEMBERS,
    vehicle_id VARCHAR NOT NULL REFERENCES VEHICLES,
    event_type VARCHAR NOT NULL,
    event_time TIMESTAMP NOT NULL,
    amount     NUMERIC(8,2)
);

--- Data -----------------------------------------------------------------------





SELECT setval('members_member_id_seq', (SELECT max(member_id) FROM MEMBERS));


--- Business-rule trigger ------------------------------------------------------
--
-- A vehicle's availability is determined by its MOST RECENT event:
--
--     Return / Cancel  -> available
--     Reserve          -> held for the member who reserved it
--     Collect          -> currently out on hire
--     Incident         -> off the road until it is returned
--
-- The trigger below refuses a 'Collect' that would break those rules.  It is
-- created AFTER the historical data is loaded, so the load is not validated
-- against it.
--------------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION UDF_BI_COLLECT() RETURNS TRIGGER AS $$
DECLARE
    last_type   VARCHAR;
    last_member INTEGER;
BEGIN
    IF NEW.event_type = 'Collect' THEN

        SELECT E.event_type, E.member_id
          INTO last_type, last_member
          FROM BOOKING_EVENTS E
         WHERE E.vehicle_id = NEW.vehicle_id
         ORDER BY E.event_time DESC, E.event_id DESC
         LIMIT 1;

        IF last_type = 'Incident' THEN
            RAISE EXCEPTION
                'Vehicle % is off the road pending repair', NEW.vehicle_id;
        ELSIF last_type = 'Collect' THEN
            RAISE EXCEPTION
                'Vehicle % is already out on hire', NEW.vehicle_id;
        ELSIF last_type = 'Reserve' AND last_member <> NEW.member_id THEN
            RAISE EXCEPTION
                'Vehicle % is reserved by member %', NEW.vehicle_id, last_member;
        END IF;

    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER BI_COLLECT
BEFORE INSERT ON BOOKING_EVENTS
FOR EACH ROW
EXECUTE FUNCTION UDF_BI_COLLECT();

COMMIT;

ANALYZE STATIONS, MODELS, VEHICLES, MEMBERS, BOOKING_EVENTS;

\echo 'DONE! All data has been inserted.'
\set QUIET off
\set ECHO all
